(function () {
  'use strict';
  const C=window.DiscoLabCore, STORAGE='discolab-progress-v1', $=sel=>document.querySelector(sel);
  const TITLES=['Inspeccionar el equipo','Interpretar MBR y GPT','Organizar el disco','Elegir formatos','Resolver incidencias','Preguntas e informe'];
  const NAV=['Teoría',...TITLES];
  const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const num=n=>C.fmt(n), fsOptions=['NTFS','ext4','FAT32','exFAT','APFS'];
  let state,selected={diskId:'data',partId:'original'},toastTimer,persistTimer,autosaveAvailable=true;
  function randomCase(){const n=new Uint32Array(1);if(window.crypto)window.crypto.getRandomValues(n);else n[0]=Math.floor(Math.random()*10000);return C.CASES[n[0]%C.CASES.length].id;}
  try{const saved=localStorage.getItem(STORAGE);state=saved?C.validateSave(JSON.parse(saved)):C.createState(randomCase());}catch(e){state=C.createState(randomCase());}
  function statusText(){return autosaveAvailable?'Copia automática en este navegador. Guarda un archivo para cambiar de equipo.':'Usa Guardar para conservar el progreso: la copia del navegador no está disponible.';}
  function persist(){state.savedAt=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify(state));autosaveAvailable=true;}catch(e){autosaveAvailable=false;}const el=$('#save-status');if(el)el.textContent=statusText();updateProgress();}
  function schedulePersist(){clearTimeout(persistTimer);persistTimer=setTimeout(persist,180);}
  function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),5500);}
  function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
  function safeFilename(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,65)||'alumnado';}
  function saveFile(){clearTimeout(persistTimer);persist();download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'DiscoLab_Progreso_'+safeFilename(state.names)+'.json');toast('Progreso guardado. Conserva el archivo JSON para continuar en otro equipo.');}
  function options(items,value,placeholder='Selecciona…'){return '<option value="">'+esc(placeholder)+'</option>'+items.map(item=>{const v=Array.isArray(item)?item[0]:item,t=Array.isArray(item)?item[1]:item;return '<option value="'+esc(v)+'"'+(String(v)===String(value)?' selected':'')+'>'+esc(t)+'</option>';}).join('');}
  function selectAnswer(id,label,items){return '<div class="field"><label for="answer-'+id+'">'+esc(label)+'</label><select id="answer-'+id+'" data-answer="'+id+'">'+options(items,state.answers[id])+'</select></div>';}
  function longAnswer(id,label,note='Escribe al menos una frase completa.'){return '<div class="field full"><label for="answer-'+id+'">'+esc(label)+'</label><textarea id="answer-'+id+'" data-answer="'+id+'" maxlength="8000">'+esc(state.answers[id]||'')+'</textarea><div class="answer-note">'+esc(note)+'</div></div>';}
  function checklist(list){return '<ul class="checklist">'+list.map(([text,ok])=>'<li class="'+(ok?'checked':'')+'"><span class="check-icon" aria-hidden="true">'+(ok?'✓':'')+'</span><span>'+esc(text)+'</span></li>').join('')+'</ul>';}
  function work(){return C.workState(state);}
  function firstSelection(){const d=work().disks.find(d=>!d.protected&&d.parts.some(p=>p.type!=='reserved'));const p=d.parts.find(p=>p.type==='volume'||p.type==='unallocated');return {diskId:d.id,partId:p.id};}

  function render(){
    const done=C.completion(state);
    const descriptions=['Consulta las ideas que utilizarás en toda la práctica.','Consulta el equipo y distingue cada nivel de organización.','Interpreta las tablas de particiones y sus límites.','Resuelve un ejemplo guiado y otro autónomo, conservando los archivos.','Relaciona las funciones de cada formato con el uso del dispositivo.','Elige un plan, observa sus consecuencias y analiza el resultado.','Responde al cuestionario y descarga el informe de tu trabajo.'];
    $('#app').innerHTML=`<div class="layout"><aside class="sidebar">
      <div><div class="brand"><span class="brand-icon" aria-hidden="true"><span></span><span></span><span></span></span>DiscoLab</div><div class="muted small" style="margin-top:6px">Digitalización · 4.º ESO</div></div>
      <nav class="nav" aria-label="Actividades">${NAV.map((title,i)=>`<button class="nav-item ${state.stage===i?'active ':''}${i>0&&done[i-1]?'done':''}" data-action="stage" data-stage="${i}" ${state.stage===i?'aria-current="step"':''}><span class="step-number">${i>0&&done[i-1]?'✓':i}</span><span>${esc(title)}</span></button>`).join('')}</nav>
      <div class="sidebar-progress"><div class="row between small"><span>Apartados registrados</span><span id="progress-count">${done.filter(Boolean).length}/6</span></div><div class="progress-track"><div id="progress-fill" class="progress-fill" style="width:${done.filter(Boolean).length/6*100}%"></div></div><p class="small progress-note">Indica que hay respuestas y operaciones; no evalúa su contenido.</p></div>
      <div class="sidebar-note"><div class="simulation-note"><strong>Solo discos virtuales</strong><p class="small" style="margin-top:7px">Las operaciones afectan a los discos de esta simulación.</p></div><div class="reset-buttons"><button class="btn compact" data-action="reset-current" ${state.stage===0?'disabled':''}>Reiniciar actividad actual</button><button class="btn compact" data-action="reset">Reiniciar simulación</button></div></div>
      </aside><main class="main"><header class="topbar"><div class="topbar-title">Laboratorio de almacenamiento<small>Discos, particiones y archivos</small></div><div class="toolbar"><button class="btn" data-action="save">Guardar</button><button class="btn" data-action="load">Cargar</button><button class="btn" data-action="help">Ayuda y glosario</button></div></header>
      <div class="workspace" id="workspace" tabindex="-1"><div class="student-bar"><div class="names-field"><label for="names">Nombre(s) del alumnado</label><textarea id="names" maxlength="2000" placeholder="Nombres de todos los miembros del grupo">${esc(state.names)}</textarea></div><div><label for="group">Grupo / clase</label><input id="group" maxlength="100" value="${esc(state.group)}" placeholder="4.º ESO"></div></div>
      <div class="mission-heading"><div><div class="kicker">${state.stage===0?'Punto de partida':'Actividad '+state.stage+' de 6'}</div><h1>${NAV[state.stage]}</h1><p class="muted">${descriptions[state.stage]}</p></div></div>
      <div id="stage-content">${stageContent()}</div><div class="footer-nav"><button class="btn" data-action="previous" ${state.stage===0?'disabled':''}>Anterior</button><span class="save-indicator" id="save-status">${statusText()}</span><button class="btn primary" data-action="next" ${state.stage===6?'disabled':''}>Siguiente</button></div></div></main></div>`;
    bindInputs();updateProgress();
  }
  function stageContent(){return [theoryView,inspectView,schemesView,organizeView,formatsView,incidentsView,reportView][state.stage]();}
  function updateProgress(){
    const done=C.completion(state),count=done.filter(Boolean).length;
    const n=$('#progress-count'),bar=$('#progress-fill');if(n)n.textContent=count+'/6';if(bar)bar.style.width=count/6*100+'%';
    document.querySelectorAll('.nav-item').forEach((el,i)=>{const recorded=i>0&&done[i-1];el.classList.toggle('done',!!recorded);el.querySelector('.step-number').textContent=recorded?'✓':i;});
    const readiness=$('#report-readiness');if(readiness)readiness.innerHTML=reportReadiness();
    const quizCount=$('#quiz-count');if(quizCount)quizCount.textContent=C.quizQuestions(state).filter(q=>state.quizAnswers[q.id]).length+'/12';
    const writtenCount=$('#written-count');if(writtenCount)writtenCount.textContent=C.finalQuestions(state).filter(q=>String(state.finalAnswers[q.id]||'').trim()).length+'/1';
  }
  function bindInputs(){
    $('#names').addEventListener('input',e=>{state.names=e.target.value;schedulePersist();});
    $('#group').addEventListener('input',e=>{state.group=e.target.value;schedulePersist();});
    document.querySelectorAll('[data-answer]').forEach(el=>el.addEventListener(el.tagName==='SELECT'?'change':'input',e=>{state.answers[el.dataset.answer]=e.target.value;delete state.feedback[state.stage];schedulePersist();}));
    document.querySelectorAll('[data-format-choice]').forEach(el=>el.addEventListener('change',e=>{const id=el.dataset.formatChoice,old=state.formatTests[id]||{};state.formatTests[id]={...old,choice:e.target.value,ok:false,message:'',testedAt:null};schedulePersist();const slot=$('#format-result-'+id);if(slot)slot.innerHTML='';const badge=el.closest('section').querySelector('.badge.good');if(badge)badge.remove();}));
    document.querySelectorAll('[data-format-why]').forEach(el=>el.addEventListener('input',e=>{const id=el.dataset.formatWhy;state.formatTests[id]={...state.formatTests[id],why:e.target.value};schedulePersist();}));
    document.querySelectorAll('[data-incident-reflection]').forEach(el=>el.addEventListener('input',e=>{const id=el.dataset.incidentReflection;state.incidentTests[id]={...state.incidentTests[id],reflection:e.target.value};schedulePersist();}));
    document.querySelectorAll('[data-quiz]').forEach(el=>el.addEventListener('change',e=>{state.quizAnswers[el.dataset.quiz]=e.target.value;schedulePersist();}));
    document.querySelectorAll('[data-incident-plan]').forEach(el=>el.addEventListener('change',e=>{const id=el.dataset.incidentPlan;state.incidentTests[id]={...state.incidentTests[id],selectedPlan:e.target.value};schedulePersist();}));
    document.querySelectorAll('[data-final]').forEach(el=>el.addEventListener('input',e=>{state.finalAnswers[el.dataset.final]=e.target.value;schedulePersist();}));
  }
  function nativeWindow(title,content){return '<section class="native-window" aria-label="'+esc(title)+'"><div class="native-title"><strong>'+esc(title)+'</strong><span class="badge">Simulación</span><span class="window-controls" aria-hidden="true">− □</span></div><div class="native-menu">Archivo &nbsp; Acción &nbsp; Ver &nbsp; Ayuda</div><div class="native-body">'+content+'</div></section>';}
  function inspectView(){
    const c=C.config(state.caseId);
    return '<div class="card brief"><strong>Encargo</strong><p>El equipo ya está funcionando. Consulta los datos que aparecen abajo y responde. Cuenta también las particiones reservadas, aunque no tengan letra. El USB y el disco externo son dispositivos físicos diferentes.</p></div><div class="grid-2"><div>'+nativeWindow('Información del sistema','<table class="info-table"><tbody><tr><th>Nombre del sistema</th><td>DESKTOP-DIGITAL</td></tr><tr><th>Sistema operativo</th><td>Windows</td></tr><tr><th>Modo de BIOS</th><td><strong>UEFI</strong></td></tr><tr><th>Fabricante de la placa base</th><td>'+esc(c.motherboard)+'</td></tr><tr><th>Ubicación del firmware</th><td>Memoria no volátil de la placa base</td></tr></tbody></table><p class="small muted" style="margin-top:12px">Windows conserva la etiqueta «Modo de BIOS» aunque el valor sea UEFI. El firmware y el sistema operativo cumplen funciones distintas.</p>')+'</div><div class="card"><h2>Qué estás consultando</h2><p>El firmware inicializa el hardware y localiza un cargador de arranque antes de que empiece a funcionar el sistema operativo.</p><p>Un <strong>disco</strong> es el dispositivo físico. Las <strong>particiones</strong> son divisiones lógicas dentro del disco. El <strong>sistema de archivos</strong> organiza la información de una partición.</p><p class="small muted">La consulta de las tablas siguientes es de solo lectura.</p></div></div>'+nativeWindow('Administración de discos · consulta',diskTable(state.initialDisks,false)+diskMaps(state.initialDisks,false))+partitionExplanation()+'<div class="card"><h2>Ficha de inspección</h2><div class="fields">'+selectAnswer('firmware','¿Qué firmware / modo usa el equipo?',['UEFI','BIOS legado'])+selectAnswer('physical','¿Cuántos discos físicos aparecen?',['2','3','4','9'])+selectAnswer('partitions','¿Cuántas particiones aparecen en total?',['4','6','7','9','10'])+selectAnswer('system','¿En qué disco está instalado Windows?',[['0','Disco 0'],['1','Disco 1'],['2','Disco 2'],['3','Disco 3']])+selectAnswer('scheme','¿Qué esquema tiene el disco de datos?',['MBR','GPT','NTFS','exFAT'])+selectAnswer('windowsFs','¿Qué sistema de archivos tiene Windows?',fsOptions)+longAnswer('noLetter','¿Por qué no todas las particiones aparecen con una letra en el Explorador?','Relaciona tu respuesta con las funciones de EFI, MSR y recuperación explicadas arriba.')+'</div></div>';
  }
  function partitionExplanation(){return '<section class="card"><h2>¿Por qué algunas particiones no tienen letra?</h2><p>El <strong>Explorador</strong> muestra unidades que Windows presenta para trabajar con archivos, como C: o D:. <strong>Administración de discos</strong> muestra también las particiones reservadas y su posición, aunque no tengan letra.</p><div class="table-wrap"><table class="table"><thead><tr><th>Partición</th><th>Función</th><th>Cómo aparece habitualmente</th></tr></thead><tbody><tr><td>Sistema EFI</td><td>Guarda archivos que utiliza UEFI para iniciar el sistema.</td><td>Sin letra; no es una unidad para documentos.</td></tr><tr><td>Reservada MSR</td><td>Windows reserva una pequeña zona en discos GPT. No tiene sistema de archivos para guardar nuestros documentos.</td><td>Sin letra.</td></tr><tr><td>Recuperación</td><td>Contiene herramientas para recuperar o reparar el sistema.</td><td>Sin letra; se utiliza cuando se necesita recuperación.</td></tr><tr><td>Windows y volúmenes de datos</td><td>Contienen el sistema o nuestros archivos.</td><td>Pueden tener letras como C:, D: o F:.</td></tr></tbody></table></div><p>La letra es una forma de acceder a un volumen en Windows; <strong>no es obligatoria para todas las particiones</strong>. No asignes letras a las reservas de este equipo. Una partición de datos tampoco tiene por qué tener siempre letra: puede estar desmontada o tener otro punto de acceso.</p></section>';}
  function schemesView(){
    const c=C.config(state.caseId),gpt=c.gptPartitions;
    const block=text=>'<div class="scheme-block">'+text+'</div>';
    return '<section class="card brief"><strong>Cómo leer los tres ejemplos</strong><p>Compara dos cantidades: <strong>entradas principales de la tabla</strong> y <strong>unidades que pueden guardar datos</strong>. En MBR hay cuatro entradas principales. Una extendida ocupa una de ellas y contiene unidades lógicas; su contenedor no se suma como otra unidad de datos.</p></section><div class="grid-3">'+
      '<section class="card scheme-card"><span class="badge">A · MBR</span><h2 style="margin-top:10px">Cuatro primarias</h2><div class="scheme-blocks">'+[1,2,3,4].map(n=>block('Primaria '+n)).join('')+'</div><p>Cada primaria ocupa una entrada. Aquí las cuatro entradas son primarias y cada una puede guardar datos. No queda ninguna entrada principal, aunque hubiera espacio sin asignar.</p></section>'+
      '<section class="card scheme-card"><span class="badge">B · MBR</span><h2 style="margin-top:10px">Tres primarias y un contenedor</h2><div class="scheme-blocks">'+[1,2,3].map(n=>block('Primaria '+n)).join('')+'</div><div class="extended"><strong>Una extendida</strong><div class="scheme-blocks">'+Array.from({length:c.logical},(_,i)=>block('Lógica '+(i+1))).join('')+'</div></div><p>Las tres primarias ocupan tres entradas. La extendida ocupa la cuarta y contiene las '+c.logical+' unidades lógicas. Estas guardan datos, pero no consumen nuevas entradas de las cuatro principales. No sumes el contenedor como otra unidad.</p></section>'+
      '<section class="card scheme-card"><span class="badge">C · GPT</span><h2 style="margin-top:10px">'+gpt+' particiones independientes</h2><div class="scheme-blocks">'+Array.from({length:gpt},(_,i)=>block('Partición '+(i+1))).join('')+'</div><p>GPT utiliza otra tabla, con muchas entradas. Cada partición tiene su entrada y no se emplea la extendida de MBR. Windows admite hasta 128 particiones GPT.</p></section></div>'+
      '<section class="card"><h2>1. Compara lo que has observado</h2><div class="fields">'+
      selectAnswer('primaryUnits','A: ¿cuántas unidades de datos hay?',['3','4','5','6'])+
      selectAnswer('primaryAdd','A: ¿puede añadirse una quinta primaria sin cambiar las cuatro existentes?',[['sí','Sí, si queda espacio'],['no','No: las cuatro entradas están ocupadas']])+
      selectAnswer('mbrEntries','B: ¿cuántas entradas principales de MBR se ocupan?',[...new Set(['3','4',String(3+c.logical),String(4+c.logical)])])+
      selectAnswer('logicalUnits','B: ¿cuántas unidades de datos hay, sin contar el contenedor?',[String(2+c.logical),String(3+c.logical),String(4+c.logical)])+
      selectAnswer('gptUnits','C: ¿cuántas particiones de datos se muestran?',[String(gpt-1),String(gpt),String(gpt+1)])+
      selectAnswer('needsExtended','C: ¿se necesita una partición extendida?',[['sí','Sí'],['no','No']])+'</div></section>'+
      '<section class="card"><h2>2. Aplica la comparación a otro disco</h2><p>Un disco de datos nuevo necesita '+gpt+' particiones independientes, sin extendida. Otro disco tiene '+c.largeTB+' TB y sectores lógicos de 512 bytes. MBR permite aproximadamente 2 TB en esta escala con ese tamaño de sector; GPT admite discos mayores.</p><div class="fields">'+
      selectAnswer('six','¿Qué esquema elegirías para las '+gpt+' particiones sin extendida?',['MBR','GPT'])+
      selectAnswer('large','¿Qué esquema permite utilizar el disco completo de '+c.largeTB+' TB?',['MBR','GPT'])+
      longAnswer('schemeWhy','Justifica las dos elecciones.','Explica qué limitación evita cada elección, con tus propias palabras.')+'</div><div class="feedback">UEFI y GPT suelen utilizarse juntos, pero son conceptos diferentes: UEFI es firmware y GPT organiza las particiones. Un disco de datos MBR puede usarse en un equipo UEFI.</div></section>';
  }

  function diskTable(disks,interactive){
    return '<div class="table-wrap"><table class="table"><thead><tr><th>Volumen / partición</th><th>Disco</th><th>Esquema</th><th>Sist. archivos</th><th>Capacidad</th><th>Libre</th><th>Estado</th></tr></thead><tbody>'+disks.flatMap(d=>d.parts.filter(p=>p.type!=='unallocated').map(p=>'<tr class="'+(interactive?'selectable ':'')+(interactive&&selected.diskId===d.id&&selected.partId===p.id?'selected':'')+'" '+(interactive?'data-action="select-part" data-disk="'+esc(d.id)+'" data-part="'+esc(p.id)+'"':'')+'><td>'+esc(p.label)+(p.letter?' ('+esc(p.letter)+':)':'')+'</td><td>'+d.number+'</td><td>'+esc(d.scheme)+'</td><td>'+esc(p.fs||'—')+'</td><td>'+C.size(p.mib)+'</td><td>'+(p.type==='reserved'?'—':C.size(p.mib-C.used(p)))+'</td><td>'+esc(partStatus(p))+'</td></tr>')).join('')+'</tbody></table></div>';
  }
  function partStatus(p){if(p.type==='unallocated')return 'Sin asignar';if(p.type==='reserved')return p.label;if(p.fs==='RAW')return 'Sin formatear';if(p.protected)return 'Sistema operativo';return 'Correcto · partición de datos';}
  function diskMaps(disks,interactive,mini=false){
    return '<div class="'+(mini?'mini-disk':'')+'">'+disks.map(d=>'<div class="disk-row '+(d.failed?'device-failed':'')+'"><div class="disk-label"><strong>Disco '+d.number+'</strong><span>'+esc(d.name)+'</span><span>'+C.size(d.mib)+' · '+esc(d.scheme)+'</span>'+(d.failed?'<strong>Dispositivo averiado · volúmenes inaccesibles</strong>':'')+'</div><div class="disk-map" aria-label="Zonas del disco '+d.number+' en orden">'+d.parts.map((p,i)=>{
      const tag=interactive?'button':'div',isSelected=interactive&&selected.diskId===d.id&&selected.partId===p.id;
      return '<'+tag+' class="partition '+(p.type==='unallocated'?'unallocated ':'')+(p.type==='reserved'?'system ':'')+(isSelected?'selected':'')+'" '+(interactive?'data-action="select-part" data-disk="'+esc(d.id)+'" data-part="'+esc(p.id)+'" aria-pressed="'+isSelected+'"':'')+'><span class="part-order">Zona '+(i+1)+'</span><span class="part-title">'+esc(p.label||'Sin asignar')+(p.letter?' ('+esc(p.letter)+':)':'')+'</span><span class="part-size">'+C.size(p.mib)+'</span><span class="part-status">'+esc(d.failed?'Inaccesible':p.fs||partStatus(p))+'</span>'+(mini&&p.type==='volume'?'<span class="mini-files">'+(d.failed?'Contenido inaccesible':p.fs==='RAW'?'Archivos no consultables':p.files.length?p.files.map(f=>esc(f.name)+' · '+C.size(f.mib)).join('<br>'):'Sin archivos')+'</span>':'')+'</'+tag+'>';
    }).join('')+'</div></div>').join('')+'<p class="map-note">Las zonas se leen en orden, de izquierda a derecha y de arriba abajo. Los bloques están ampliados para leer sus etiquetas; su anchura no representa el tamaño. Consulta las cifras.</p><div class="legend"><span>Partición de datos</span><span class="protected">Partición reservada / sistema</span><span class="unalloc">Sin asignar</span></div></div>';
  }
  function diskActions(){let pair;try{pair=C.getPart(work(),selected.diskId,selected.partId);}catch(e){selected=firstSelection();pair=C.getPart(work(),selected.diskId,selected.partId);}const {disk,part}=pair,cap=C.capabilities(work(),disk.id,part.id);
    return '<div class="disk-actions"><div class="selection"><strong>Seleccionado:</strong> '+esc(part.label||'Sin asignar')+' · '+C.size(part.mib)+'<br><span class="muted small">Disco '+disk.number+(part.fs?' · '+part.fs:'')+'</span></div>'+[['create','Nuevo volumen simple'],['shrink','Reducir volumen'],['extend','Extender volumen'],['format','Formatear'],['letter','Cambiar letra'],['delete','Eliminar volumen']].map(([action,title])=>'<button class="btn compact '+(action==='delete'?'danger':'')+'" data-action="disk-operation" data-operation="'+action+'" '+(!cap[action]?'disabled':'')+'>'+title+'</button>').join('')+'<button class="btn compact" data-action="properties">Propiedades</button></div>';
  }
  function filesView(){return '<div class="feedback">Las copias se hacen desde el Explorador, no desde Administración de discos. Copiar archivos conserva el origen.</div>'+work().disks.flatMap(d=>d.parts.filter(p=>p.type==='volume').map(p=>'<div class="file-volume"><h3><span>'+esc(p.label)+' ('+esc(p.letter||'sin letra')+':)</span><span class="badge">Disco '+d.number+' · '+p.fs+'</span></h3><div class="small muted">'+C.size(C.used(p))+' utilizados de '+C.size(p.mib)+'</div><div class="file-list">'+(p.fs==='RAW'?'<div class="feedback warn">Debes formatear el volumen para poder utilizarlo.</div>':p.protected?'<div class="muted">Archivos del sistema operativo · consulta protegida</div>':p.files.length?p.files.map(f=>'<div class="file-item"><span>'+esc(f.name)+'</span><span>'+C.size(f.mib)+'</span></div>').join(''):'<span class="muted">Este volumen no contiene archivos de la práctica.</span>')+'</div><button class="btn compact" data-action="copy" data-disk="'+esc(d.id)+'" data-part="'+esc(p.id)+'" '+(p.protected||p.fs==='RAW'||!p.files.length?'disabled':'')+'>Copiar archivos…</button></div>')).join('');}
  function organizeView(){
    const independent=state.workArea==='independent';
    return '<div class="exercise-tabs" role="group" aria-label="Ejercicios de organización"><button class="btn '+(!independent?'primary':'')+'" data-action="work-area" data-area="guided" aria-pressed="'+!independent+'">3A · Ejemplo guiado</button><button class="btn '+(independent?'primary':'')+'" data-action="work-area" data-area="independent" aria-pressed="'+independent+'">3B · Trabajo autónomo</button></div>'+(independent?independentView():guidedView());
  }
  function independentView(){
    const q=C.challengeConfig(state);
    return `<section class="card brief"><strong>Ahora te toca resolver otro encargo</strong><p>Trabajas con otros dos discos virtuales. El ejemplo 3A conserva su estado y puedes consultarlo. Decide las operaciones de este encargo y revisa su resultado.</p><p>El volumen <strong>${esc(q.original)}</strong> ocupa ${q.total} GB. Conserva sus tres archivos, deja una copia comprobada en el disco externo y reorganiza el SSD de práctica con este reparto:</p>
      <div class="table-wrap"><table class="table"><thead><tr><th>Zona final</th><th>Capacidad</th><th>Requisitos</th></tr></thead><tbody>
      <tr><td>${esc(q.original)}</td><td>${q.keep} GB</td><td>Conservar NTFS y sus tres archivos originales.</td></tr>
      <tr><td>${esc(q.localLabel)}</td><td>${q.local} GB</td><td>Nuevo volumen NTFS para Windows con copia de los tres archivos.</td></tr>
      <tr><td>${esc(q.sharedLabel)}</td><td>${q.shared} GB</td><td>Nuevo volumen exFAT para lectura y escritura en Windows y macOS, con copia de los tres archivos.</td></tr>
      <tr><td>Reserva futura</td><td>${q.reserve} GB</td><td>Espacio sin asignar, a continuación de los dos nuevos volúmenes.</td></tr>
      </tbody></table></div><p>Utiliza letras libres y las etiquetas del encargo. La MSR de 16 MB permanece reservada. El informe recogerá capacidades, formatos, archivos y operaciones para revisar tu trabajo.</p></section>
      <div class="tool-tabs" role="group" aria-label="Herramienta"><button class="tool-tab ${state.tool==='disks'?'active':''}" data-action="tool" data-tool="disks">Administración de discos</button><button class="tool-tab ${state.tool==='files'?'active':''}" data-action="tool" data-tool="files">Explorador de archivos</button></div>
      ${nativeWindow(state.tool==='disks'?'Administración de discos · ejercicio autónomo':'Explorador de archivos · ejercicio autónomo',state.tool==='disks'?diskTable(work().disks,true)+diskMaps(work().disks,true)+diskActions():filesView())}
      <section class="card"><h2>Últimas operaciones</h2>${logView(6)}<p class="small muted">El progreso conserva por separado los discos de 3A y 3B.</p></section>`;
  }

  function guidedView(){
    const c=C.config(state.caseId);
    return `<div class="card brief"><strong>Encargo</strong><p>El volumen <strong>${esc(c.original)}</strong> tiene <strong>${c.total} GB</strong> y contiene documentos. Conserva esos archivos y organiza el disco de datos así:</p><div class="grid-3"><div><strong>${esc(c.original)}</strong><br>${c.keep} GB · NTFS</div><div><strong>${esc(c.target)}</strong><br>${c.project} GB · NTFS</div><div><strong>Reserva futura</strong><br>${c.reserve} GB sin asignar</div></div></div>
    <section class="card guide-card"><h2>Guía de trabajo, paso a paso</h2><p>Puedes alternar las dos herramientas de abajo. <strong>Explorador</strong> copia archivos; <strong>Administración de discos</strong> cambia los volúmenes. Copiar no mueve ni elimina los originales.</p>
    <ol class="guided-steps">
      <li><strong>Haz una copia antes de cambiar el disco.</strong> Abre <em>Explorador de archivos</em>, localiza ${esc(c.original)} (${c.letter}:) en el disco 1 y pulsa <em>Copiar archivos…</em>. En Destino elige <em>Copia externa (F:), disco 2</em> y pulsa Copiar. Comprueba en el Explorador que aparecen los mismos nombres en el origen y en la copia. Otra partición del disco 1 no protegería frente a una avería de ese disco.</li>
      <li><strong>Calcula cuánto quitar al volumen original.</strong> El diálogo de reducción pide la <em>cantidad que quieres reducir</em>, no el tamaño final. Resta el tamaño final pedido al tamaño actual, o suma el nuevo volumen y la reserva. En los cuadros de este gestor, como en la interfaz de Windows modelada, introduce MB multiplicando los GB mostrados por 1.024. No uses esa relación como una definición general de las unidades decimales.</li>
      <li><strong>Reduce, conservando los archivos.</strong> Vuelve a Administración de discos, selecciona ${esc(c.original)} en el disco 1 y pulsa <em>Reducir volumen</em>. Introduce la cantidad calculada en MB y aplica. El volumen se hace más pequeño y aparece <em>Sin asignar</em> justo después. El máximo disponible tiene en cuenta los datos y la ubicación de archivos que no se pueden mover.</li>
      <li><strong>Crea la nueva partición, todavía sin formatear.</strong> Selecciona el espacio sin asignar del disco 1, pulsa <em>Nuevo volumen simple</em> e introduce solo el tamaño pedido para ${esc(c.target)}, convertido a MB. Elige una letra libre y crea sin formatear. Quedará una zona <em>RAW</em> y, después, la reserva sin asignar. La etiqueta del volumen se establece al formatear.</li>
      <li><strong>Observa por qué crear y formatear son operaciones distintas.</strong> En el Explorador, usa Copiar archivos desde ${esc(c.original)} y elige el volumen RAW como destino. La copia se detiene porque todavía no hay un sistema de archivos utilizable. Cierra el diálogo: este intento forma parte de la práctica y queda en el registro.</li>
      <li><strong>Prepara el sistema de archivos.</strong> En Administración de discos selecciona únicamente el volumen nuevo, pulsa <em>Formatear</em>, elige NTFS y escribe <strong>${esc(c.target)}</strong> como etiqueta. El formato rápido también hace que los archivos anteriores de ese volumen dejen de estar disponibles. Aquí estás formateando un volumen nuevo y vacío.</li>
      <li><strong>Copia y consulta el resultado.</strong> Desde el Explorador copia los archivos de ${esc(c.original)} a ${esc(c.target)}. Revisa nombres y tamaños en las tres ubicaciones: original, copia externa y nuevo volumen. En Administración de discos compara las capacidades con el encargo y conserva la reserva sin asignar.</li>
    </ol>
    <details class="operation-explanation"><summary>¿Qué hacen las otras operaciones?</summary><p><strong>Extender volumen:</strong> añade espacio sin asignar inmediatamente a la derecha del volumen NTFS y en el mismo disco. Conserva los archivos. Si hay otra partición entre medias, la opción no está disponible: el espacio libre dentro de esa otra partición no sirve. Lo estudiarás en la actividad 5.</p><p><strong>Eliminar volumen:</strong> quita la partición y deja su zona sin asignar; sus archivos dejan de estar disponibles. <strong>Formatear</strong> mantiene la partición y prepara su sistema de archivos. <strong>Cambiar letra</strong> cambia su identificación, conservando el contenido. <strong>Propiedades</strong> permite consultar sin modificar.</p></details>
    </section><div class="tool-tabs" role="group" aria-label="Herramienta"><button class="tool-tab ${state.tool==='disks'?'active':''}" data-action="tool" data-tool="disks">Administración de discos</button><button class="tool-tab ${state.tool==='files'?'active':''}" data-action="tool" data-tool="files">Explorador de archivos</button></div>
    ${nativeWindow(state.tool==='disks'?'Administración de discos':'Explorador de archivos',state.tool==='disks'?diskTable(work().disks,true)+diskMaps(work().disks,true)+diskActions():filesView())}
    <div class="card"><h2>Últimas operaciones</h2>${logView(6)}<p class="small muted" style="margin-top:10px">El informe conserva el estado de los discos y todo el registro de operaciones para que el profesor pueda revisar tu proceso.</p></div>`;
  }
  function filesystemTable(){return '<div class="table-wrap"><table class="table filesystem-table"><thead><tr><th>Formato y uso</th><th>Ventajas</th><th>Limitaciones</th></tr></thead><tbody>'+C.filesystemFacts().map(f=>'<tr><td><strong>'+f.id+'</strong><br>'+esc(f.use)+'</td><td>'+esc(f.pros)+'</td><td>'+esc(f.cons)+'</td></tr>').join('')+'</tbody></table></div>';}
  function theoryView(){return `<div class="card brief"><strong>Antes de empezar</strong><p>Esta práctica trabaja con un equipo que ya tiene sistema operativo y con discos virtuales. Consultarás su organización, conservarás archivos y analizarás cambios sobre volúmenes. Puedes volver a esta pestaña cuando lo necesites.</p></div>
    <section class="card"><h2>Firmware y arranque</h2><p>Al encender el ordenador, el sistema operativo todavía no funciona. Primero se ejecuta el <strong>firmware</strong>, almacenado en memoria no volátil de la placa base. Inicializa el hardware, ofrece servicios de prearranque y localiza un cargador de arranque.</p><p>Es como el encargado de abrir el ordenador por la mañana: prepara lo necesario para empezar. En equipos actuales suele ser <strong>UEFI</strong> (<em>Unified Extensible Firmware Interface</em>). El término <strong>BIOS</strong> (<em>Basic Input/Output System</em>) se sigue usando coloquialmente, pero BIOS legado y UEFI son tecnologías distintas.</p></section>
    <section class="card"><h2>Discos, particiones y volúmenes</h2><p>Un disco duro o SSD es un dispositivo físico. Las <strong>particiones</strong> son divisiones lógicas: como los compartimentos de un armario, separan usos sin convertirlo en varios armarios. Pueden alojar sistemas operativos, datos, recuperación o intercambio.</p><p>En esta práctica cada volumen de datos corresponde a una partición. Una letra como D: identifica una unidad en Windows; no identifica necesariamente un disco físico completo. EFI, MSR y recuperación suelen carecer de letra porque cumplen funciones de arranque, reserva y reparación. Se consultan en Administración de discos, pero no se presentan como unidades de documentos en el Explorador. La etiqueta es un nombre descriptivo; cambiarla no cambia la letra de las rutas.</p></section>
    <section class="card"><h2>MBR y GPT: el índice de las particiones</h2><p><strong>MBR</strong> (<em>Master Boot Record</em>) es un esquema histórico. Tiene cuatro entradas principales: se pueden usar para primarias, o reservar una para una <strong>extendida</strong> que contenga unidades lógicas. Con sectores lógicos de 512 bytes, su direccionamiento limita la capacidad utilizable a aproximadamente 2 TB en la escala del gestor.</p><p><strong>GPT</strong> (<em>GUID Partition Table</em>) es el esquema moderno habitual junto con UEFI. Permite muchas particiones y discos grandes; Windows admite hasta 128 particiones GPT. <strong>GUID</strong> significa <em>Globally Unique Identifier</em>.</p><p>Firmware y esquema son niveles diferentes. Un equipo UEFI puede usar un disco de datos MBR; GPT y NTFS tampoco son alternativas: GPT describe las particiones y NTFS organiza archivos dentro de un volumen.</p></section>
    <section class="card"><h2>Sistemas de archivos: organizar cada compartimento</h2><p>Un <strong>sistema de archivos</strong> organiza nombres, carpetas, metadatos y bloques de datos, como el sistema de clasificación de una biblioteca. <strong>Particionar</strong> divide el disco; <strong>formatear</strong> crea o prepara un sistema de archivos sobre una partición.</p>${filesystemTable()}</section>
    <section class="card"><h2>Espacio disponible y cambios en los volúmenes</h2><p><strong>Espacio libre:</strong> está dentro de un volumen y puede guardar archivos. <strong>Espacio sin asignar:</strong> todavía no pertenece a una partición. Reducir un volumen crea espacio sin asignar a su derecha; ampliarlo utiliza espacio contiguo del mismo disco. Ambos cambios pueden conservar los archivos, aunque en equipos reales se hace copia antes.</p><p>Formatear y eliminar hacen que los archivos anteriores dejen de estar disponibles normalmente. Formatear mantiene la partición; eliminar la quita. El formato rápido tampoco conserva los archivos y no es un borrado seguro.</p><p class="small muted">Los tamaños se rotulan MB, GB y TB como en la interfaz de Windows modelada. Sus cuadros de tamaño usan la escala binaria: aquí, 1 GB mostrado equivale a 1.024 MB del cuadro. En las especificaciones comerciales, MB y GB son unidades decimales y la conversión es distinta.</p></section>
    <section class="card"><h2>Seguridad y copia de archivos</h2><p>Consultar las particiones del equipo real es seguro. Modificarlas puede provocar pérdida de datos o impedir el arranque: observar el plano de una casa es distinto de mover sus tabiques. Crea, elimina, reduce o formatea únicamente en una <strong>máquina virtual</strong> o con discos de práctica expresamente preparados.</p><p>Copiar conserva el origen y añade los archivos al destino. Una copia en otro dispositivo físico protege mejor frente a la avería del disco original que otra partición del mismo disco. Comprueba siempre que los archivos copiados están disponibles.</p><p><strong>Guardar</strong> descarga el progreso para continuar después. <strong>Cargar</strong> recupera discos y respuestas. Al final, el PDF recoge tu trabajo y <strong>no borra el progreso</strong>.</p></section>`;}

  function formatsView(){return '<section class="card"><h2>Antes de elegir: compara los sistemas de archivos</h2><p>La elección depende del tamaño de cada archivo, los sistemas que leerán y escribirán la unidad y las funciones necesarias. La compatibilidad con un dispositivo concreto se consulta en su ficha.</p>'+filesystemTable()+'</section><div class="card brief"><strong>Encargo</strong><p>Lee cada ficha, elige un sistema de archivos y justifica tu decisión. Simula su uso y observa las funciones disponibles; el profesor revisará tus elecciones y explicaciones.</p></div>'+C.formatCases(state).map((item,i)=>{const t=state.formatTests[item.id]||{};return '<section class="card test-card"><span class="badge">Dispositivo '+(i+1)+' · '+esc(item.device)+'</span><h2 style="margin-top:12px">'+esc(item.title)+'</h2><p>'+esc(item.prompt)+'</p><div class="fields"><div><label for="format-choice-'+item.id+'">Sistema de archivos</label><select id="format-choice-'+item.id+'" data-format-choice="'+item.id+'">'+options(fsOptions,t.choice)+'</select></div><div><label for="format-why-'+item.id+'">¿Por qué lo eliges?</label><textarea id="format-why-'+item.id+'" data-format-why="'+item.id+'" maxlength="8000">'+esc(t.why||'')+'</textarea></div></div><button class="btn" data-action="test-format" data-id="'+item.id+'">Simular uso del dispositivo</button><div id="format-result-'+item.id+'">'+(t.message?'<div class="feedback"><strong>Observación de la simulación</strong><p>'+esc(t.message)+'</p></div>':'')+'</div></section>';}).join('');}

  function incidentsView(){return '<section class="card brief"><strong>Elige, ejecuta y analiza</strong><p>En cada incidencia observa el encargo y los discos, elige una alternativa y ejecútala. Verás el resultado de ese plan y después escribirás <strong>qué ha cambiado y si cumple el encargo</strong>, explicando por qué.</p><p class="small">Hay una ejecución por incidencia. Reiniciar esta actividad permite rehacer la reflexión, pero conserva las decisiones ejecutadas y sus consecuencias.</p></section>'+C.incidentCases(state).map((item,i)=>{
    const t=state.incidentTests[item.id]||{},locked=!!t.active;
    return '<section class="card"><span class="badge">Incidencia '+(i+1)+'</span><h2 style="margin-top:10px">'+esc(item.title)+'</h2><p>'+esc(item.prompt)+'</p><h3>Situación inicial</h3>'+diskMaps(item.disks,false,true)+
      '<fieldset class="incident-plan"><legend>Elige una alternativa</legend>'+item.plans.map((plan,j)=>'<label><input type="radio" name="incident-'+item.id+'" data-incident-plan="'+item.id+'" value="'+plan.id+'" '+((t.selectedPlan||t.plan)===plan.id?'checked':'')+' '+(locked?'disabled':'')+'><span><strong>'+String.fromCharCode(65+j)+'.</strong> '+esc(plan.text)+'</span></label>').join('')+'</fieldset>'+
      '<button class="btn primary" data-action="test-incident" data-id="'+item.id+'" '+(locked?'disabled':'')+'>'+(locked?'Plan ejecutado':'Ejecutar el plan elegido')+'</button>'+
      (t.message?'<div class="feedback"><strong>Resultado de las acciones</strong><p>'+esc(t.message).replace(/\n/g,'<br>')+'</p></div>':'')+
      (t.after?'<h3 style="margin-top:16px">Discos después del plan</h3>'+diskMaps(t.after,false,true)+'<div class="field"><label for="incident-reflection-'+item.id+'">¿Qué ha cambiado y qué archivos siguen disponibles? ¿El plan elegido es correcto para este encargo? Explica por qué y, si no lo cumple, qué habría que hacer de otra manera.</label><textarea id="incident-reflection-'+item.id+'" data-incident-reflection="'+item.id+'" maxlength="8000">'+esc(t.reflection||'')+'</textarea></div>':'')+'</section>';
  }).join('');}

  function reportReadiness(){const done=C.completion(state);return checklist(TITLES.map((t,i)=>[t,done[i]]))+'<p class="small muted">La marca indica que se han registrado las respuestas y operaciones del apartado. Su contenido se revisa con el profesor.</p>';}

  function reportView(){return '<div class="card brief"><strong>Cuestionario final</strong><p>Responde a las doce preguntas tipo test y a una pregunta de redacción, con tus propias palabras. Puedes consultar la teoría y tus operaciones. El informe recoge las opciones que hayas elegido para que las revise el profesor.</p></div><section class="card"><h2>Doce preguntas tipo test</h2>'+C.quizQuestions(state).map((q,i)=>'<fieldset class="quiz-question"><legend><span class="question-number">'+(i+1)+'.</span> '+esc(q.text)+'</legend>'+q.options.map(o=>'<label class="quiz-option"><input type="radio" name="quiz-'+q.id+'" data-quiz="'+q.id+'" value="'+o.id+'" '+(state.quizAnswers[q.id]===o.id?'checked':'')+'><span><strong>'+o.id.toUpperCase()+'.</strong> '+esc(o.text)+'</span></label>').join('')+'</fieldset>').join('')+'</section><section class="card"><h2>Una diferencia, con tus palabras</h2>'+C.finalQuestions(state).map((q,i)=>'<div class="question"><div class="question-number">Redacción '+(i+1)+'</div><label for="final-'+q.id+'">'+esc(q.text)+'</label><textarea id="final-'+q.id+'" data-final="'+q.id+'" maxlength="10000">'+esc(state.finalAnswers[q.id]||'')+'</textarea></div>').join('')+'</section><section class="card"><h2>Informe de la práctica</h2><div class="report-summary"><div class="stat"><span class="small muted">Preguntas tipo test respondidas</span><strong id="quiz-count">'+C.quizQuestions(state).filter(q=>state.quizAnswers[q.id]).length+'/12</strong></div><div class="stat"><span class="small muted">Respuestas de redacción</span><strong id="written-count">'+C.finalQuestions(state).filter(q=>String(state.finalAnswers[q.id]||'').trim()).length+'/1</strong></div><div class="stat"><span class="small muted">Operaciones registradas</span><strong>'+state.operations.length+'</strong></div></div><div id="report-readiness" style="margin-top:18px">'+reportReadiness()+'</div><div class="row"><button class="btn primary" data-action="pdf" id="pdf-button">Generar PDF de la práctica</button><button class="btn" data-action="save">Guardar también el progreso</button></div><p class="small muted" style="margin-top:12px"><strong>Generar el PDF no borra nada.</strong> Puedes seguir trabajando, guardar y generar otro informe. Incluye los discos iniciales y finales, archivos, respuestas, simulaciones, reflexiones y todo el registro de operaciones.</p></section><details class="card"><summary>Ver el registro completo</summary>'+logView()+'</details>';}

  function logView(limit){const list=limit?state.operations.slice(-limit).reverse():state.operations;return '<div class="operation-log">'+(list.length?list.map(o=>'<div class="operation-entry"><time>'+esc(new Date(o.at).toLocaleString('es-ES'))+' · '+esc(o.status==='error'?'Intento detenido':o.status==='info'?'Consulta':'Operación')+'</time>'+esc(o.message)+'</div>').join(''):'<div class="empty">Todavía no hay operaciones registradas.</div>')+'</div>';}
  function openModal(title,body,footer){const m=$('#modal');m.innerHTML='<div class="modal-head"><h2 id="modal-title">'+esc(title)+'</h2><button class="btn ghost" data-action="close-modal" aria-label="Cerrar ventana">✕</button></div><div class="modal-body">'+body+'</div>'+(footer?'<div class="modal-foot">'+footer+'</div>':'');m.showModal();const first=m.querySelector('input:not([type=checkbox]),select,textarea');if(first)first.focus();}
  function closeModal(){if($('#modal').open)$('#modal').close();}
  function confirmModal(title,message,onYes,yesText='Continuar'){openModal(title,'<p>'+esc(message)+'</p>','<button class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" id="confirm-yes">'+esc(yesText)+'</button>');$('#confirm-yes').onclick=()=>{closeModal();onYes();};}

  function reset(){confirmModal('Reiniciar la simulación','Se reiniciarán los discos, las respuestas y el registro de la práctica actual. Guarda antes el progreso que quieras conservar.',()=>{const names=state.names,group=state.group;state=C.createState(state.caseId);state.names=names;state.group=group;selected={diskId:'data',partId:'original'};persist();render();toast('La simulación vuelve a su estado inicial.');},'Reiniciar');}
  function setStage(n){state.stage=Math.max(0,Math.min(6,n));persist();render();window.scrollTo({top:0,behavior:'instant'});}
  function resetCurrent(){
    if(state.stage===0)return;
    const messages={1:'Se borrarán únicamente las respuestas de inspección.',2:'Se borrarán únicamente las respuestas de MBR y GPT.',3:'Los discos de los ejercicios 3A y 3B volverán al estado inicial. Se mantienen las respuestas de las demás actividades.',4:'Se borrarán las elecciones, explicaciones y resultados de esta actividad.',5:'Se borrarán las reflexiones posteriores y los planes todavía no ejecutados. Las decisiones ya ejecutadas y sus resultados se conservan.',6:'Se borrarán las respuestas del cuestionario y la redacción final.'};
    confirmModal('Reiniciar actividad actual',messages[state.stage]+' El historial de operaciones y los datos del alumnado se conservan.',()=>{C.resetActivity(state);selected={diskId:'data',partId:'original'};persist();render();toast('Actividad reiniciada.');},'Reiniciar esta actividad');
  }
  function operationModal(action){
    const {disk,part,index}=C.getPart(work(),selected.diskId,selected.partId),c=C.config(state.caseId),cap=C.capabilities(work(),disk.id,part.id);if(!cap[action])return;
    let body='',title='',button='Aplicar';const field=(label,value,max)=>'<label for="op-size">'+label+'</label><input id="op-size" type="number" min="1" step="1" '+(max?'max="'+max+'"':'')+' value="'+value+'"><p class="small muted" style="margin-top:8px">'+num(C.G)+' MB del cuadro equivalen a 1 GB mostrado en este gestor de Windows. Esta escala no define las unidades decimales comerciales.</p>';
    if(action==='shrink'){title='Reducir volumen · '+part.label;body='<p>Los archivos se conservarán. La reducción deja espacio sin asignar a la derecha de este volumen.</p><table class="info-table"><tr><th>Tamaño actual</th><td>'+C.size(part.mib)+'</td></tr><tr><th>Máximo que se puede reducir</th><td>'+num(C.shrinkMax(part))+' MB</td></tr></table>'+field('Cantidad que quieres reducir, en MB','',C.shrinkMax(part));button='Reducir';}
    else if(action==='extend'){title='Extender volumen · '+part.label;body='<p>La ampliación usa el espacio sin asignar inmediatamente a la derecha. Los archivos se conservarán.</p>'+field('Espacio que quieres añadir, en MB','',disk.parts[index+1].mib);button='Extender';}
    else if(action==='create'){title='Nuevo volumen simple';const available=Array.from({length:23},(_,i)=>String.fromCharCode(68+i)).filter(l=>!C.letters(work()).includes(l));body='<p>Espacio seleccionado: <strong>'+C.size(part.mib)+'</strong>. Este paso crea la partición. El volumen se crea sin sistema de archivos; el formateo es una operación posterior.</p>'+field('Tamaño del volumen, en MB','',part.mib)+'<label for="op-letter">Letra de unidad</label><select id="op-letter">'+available.map(l=>'<option>'+l+'</option>').join('')+'</select><div class="feedback">Opción del asistente: <strong>No formatear este volumen</strong>. Estado inicial: RAW. La etiqueta se establece al formatear.</div>';button='Crear sin formatear';}
    else if(action==='format'){title='Formatear · '+part.label;const fss=['NTFS','exFAT',...(part.mib<=32*C.G?['FAT32']:[])];body='<div class="feedback warn">Formatear prepara un sistema de archivos. Los archivos anteriores dejarán de estar disponibles. Guarda una copia en otro dispositivo si necesitas conservarlos.</div><label for="op-fs">Sistema de archivos</label><select id="op-fs">'+options(fss,part.fs==='RAW'?'NTFS':part.fs)+'</select><label for="op-label" style="margin-top:12px">Etiqueta del volumen</label><input id="op-label" maxlength="32" value="'+esc(part.label)+'"><label class="row" style="margin-top:14px"><input id="op-quick" type="checkbox" checked> Formato rápido</label><p class="small muted">El formato rápido no conserva los archivos y no constituye un borrado seguro.</p>';button='Formatear';}
    else if(action==='delete'){title='Eliminar volumen · '+part.label;body='<div class="feedback warn">Se eliminará la partición y sus '+(part.files||[]).length+' archivos dejarán de estar disponibles. El espacio pasará a estar sin asignar.</div><p>Esta acción solo afecta al disco virtual '+disk.number+'.</p>';button='Eliminar volumen';}
    else if(action==='letter'){title='Cambiar letra de unidad';const available=Array.from({length:23},(_,i)=>String.fromCharCode(68+i)).filter(l=>l===part.letter||!C.letters(work()).includes(l));body='<p>Cambiar la letra identifica el volumen con otra letra y conserva sus archivos.</p><label for="op-letter">Letra</label><select id="op-letter">'+options(available,part.letter)+'</select>';button='Cambiar letra';}
    openModal(title,body+'<div id="op-error" aria-live="polite"></div>','<button class="btn" data-action="close-modal">Cancelar</button><button class="btn '+(action==='delete'?'danger':'primary')+'" id="apply-operation">'+button+'</button>');
    $('#apply-operation').onclick=()=>{const args={...selected};if($('#op-size'))args.mib=Number($('#op-size').value);if($('#op-letter'))args.letter=$('#op-letter').value;if($('#op-label'))args.label=$('#op-label').value;if($('#op-fs'))args.fs=$('#op-fs').value;if($('#op-quick'))args.quick=$('#op-quick').checked;
      const result=C.perform(work(),action,args);persist();if(!result.ok){$('#op-error').innerHTML='<div class="feedback bad">'+esc(result.message)+'</div>';return;}if(result.partId)selected.partId=result.partId;else if(action==='delete')selected=firstSelection();closeModal();render();toast(result.message);
    };
  }
  function copyModal(diskId,partId){const {part}=C.getPart(work(),diskId,partId),destinations=work().disks.flatMap(d=>d.parts.filter(p=>p.type==='volume'&&!p.protected&&!(d.id===diskId&&p.id===partId)).map(p=>[d.id+'|'+p.id,p.label+' ('+(p.letter||'sin letra')+':) · disco '+d.number+' · '+p.fs]));
    openModal('Copiar archivos · '+part.label,'<p>Se copiarán los '+part.files.length+' archivos de este volumen. Los originales permanecerán en su ubicación.</p><div class="file-list">'+part.files.map(f=>'<div class="file-item"><span>'+esc(f.name)+'</span><span>'+C.size(f.mib)+'</span></div>').join('')+'</div><label for="copy-destination">Destino</label><select id="copy-destination">'+options(destinations,'')+'</select><div id="copy-result" aria-live="polite"></div>','<button class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" id="copy-apply">Copiar</button>');
    $('#copy-apply').onclick=()=>{const value=$('#copy-destination').value;if(!value){$('#copy-result').innerHTML='<div class="feedback warn">Selecciona el destino.</div>';return;}const [destDisk,destPart]=value.split('|');const r=C.perform(work(),'copy',{sourceDisk:diskId,sourcePart:partId,destDisk,destPart});persist();if(!r.ok){$('#copy-result').innerHTML='<div class="feedback bad">'+esc(r.message)+'</div>';return;}closeModal();render();toast(r.message);};
  }
  function properties(){const {disk,part}=C.getPart(work(),selected.diskId,selected.partId);C.record(work(),'properties','Consultadas las propiedades de '+(part.label||'Sin asignar')+' en el disco '+disk.number+'.','info');persist();openModal('Propiedades del disco / volumen','<table class="info-table"><tr><th>Disco físico</th><td>Disco '+disk.number+' · '+esc(disk.name)+'</td></tr><tr><th>Esquema de particiones</th><td>'+disk.scheme+'</td></tr><tr><th>Tamaño de sector lógico</th><td>512 bytes</td></tr><tr><th>Zona seleccionada</th><td>'+esc(part.label||'Sin asignar')+'</td></tr><tr><th>Capacidad</th><td>'+C.size(part.mib)+'</td></tr><tr><th>Sistema de archivos</th><td>'+esc(part.fs||'No corresponde')+'</td></tr><tr><th>Función</th><td>'+esc(partStatus(part))+'</td></tr><tr><th>Protección</th><td>'+((disk.protected||part.protected)?'Consulta de solo lectura':'Disco de práctica')+'</td></tr></table>','<button class="btn primary" data-action="close-modal">Cerrar</button>');}
  function help(){openModal('Ayuda y glosario','<div class="help-content"><p>Puedes volver a la teoría y a las actividades desde el menú. El equipo y sus discos son una simulación.</p><ul><li><strong>Guardar:</strong> descarga un archivo JSON con discos, respuestas y registro.</li><li><strong>Cargar:</strong> abre ese JSON y continúa en el mismo punto, incluso desde otro ordenador.</li><li>El navegador conserva una copia automática cuando puede. El archivo descargado es el que permite cambiar de equipo.</li><li>El PDF se genera al final, en Preguntas e informe, y no borra el progreso.</li><li>En Organizar el disco, selecciona una zona y utiliza sus operaciones. Para copiar archivos cambia al Explorador.</li></ul><dl><dt>Firmware · UEFI · BIOS</dt><dd>El firmware está almacenado en la placa base. UEFI significa Unified Extensible Firmware Interface; BIOS, Basic Input/Output System. UEFI y BIOS legado son tecnologías diferentes.</dd><dt>MBR · GPT · GUID</dt><dd>MBR: Master Boot Record. GPT: GUID Partition Table. GUID: Globally Unique Identifier. MBR y GPT organizan las particiones; un GUID es un identificador globalmente único.</dd><dt>Partición y volumen</dt><dd>Una partición es una división lógica del disco. En esta práctica, cada volumen de datos corresponde a una partición preparada para contener un sistema de archivos.</dd><dt>EFI · MSR · recuperación</dt><dd>EFI contiene archivos de arranque UEFI. MSR es una pequeña reserva de Windows en discos GPT y no tiene sistema de archivos. Recuperación contiene herramientas para reparar el sistema. Suelen no tener letra.</dd><dt>Letra y etiqueta</dt><dd>D: es una letra que forma parte de una ruta, como D:\\Documento.pdf. Archivo es una etiqueta descriptiva. Cambiar una no cambia la otra. Asignar o cambiar una letra conserva los documentos, pero puede afectar a rutas que la utilizan.</dd><dt>Libre y sin asignar</dt><dd>Libre: espacio disponible dentro de un volumen. Sin asignar: espacio del disco que todavía no pertenece a una partición.</dd><dt>RAW</dt><dd>Windows no reconoce un sistema de archivos utilizable en ese volumen. En el disco vacío de esta práctica corresponde a un volumen creado sin formatear. En un disco real con archivos también puede indicar daños: no se debe formatear sin valorar la recuperación de datos.</dd><dt>NTFS · ext4 · FAT32 · exFAT · APFS</dt><dd>NTFS es habitual en Windows; ext4, en Linux; APFS, en Apple. FAT32 ofrece compatibilidad con muchos aparatos antiguos y limita cada archivo a 4 GB menos 1 byte. exFAT es útil para intercambio de archivos grandes entre Windows y macOS.</dd><dt>Unidades del gestor</dt><dd>Los cuadros de la interfaz de Windows modelada usan escala binaria aunque muestren MB y GB: en esta simulación, 1 GB mostrado equivale a 1.024 MB del cuadro. Las unidades comerciales MB y GB son decimales y usan otra conversión.</dd><dt>Seguridad</dt><dd>Consulta el equipo real; realiza modificaciones solo en una máquina virtual o en discos de práctica expresamente preparados. Una copia en otra partición del mismo disco no protege contra la avería física del disco.</dd></dl></div>','<button class="btn primary" data-action="close-modal">Cerrar</button>');}
  async function pdf(){if(!state.names.trim()){toast('Escribe el nombre o los nombres del alumnado antes de generar el PDF.');$('#names').focus();return;}const run=async()=>{persist();const button=$('#pdf-button');if(button){button.disabled=true;button.textContent='Generando PDF…';}try{await window.DiscoLabReport.download(state);toast('PDF generado con la práctica y todas las respuestas.');}catch(e){toast('No se ha podido generar el PDF. Guarda el progreso y vuelve a intentarlo.');console.error(e);}finally{if(button){button.disabled=false;button.textContent='Generar PDF de la práctica';}}};if(!C.completion(state).every(Boolean))confirmModal('Informe con apartados pendientes','Hay actividades o respuestas pendientes. El informe las identificará como pendientes y conservará todo lo realizado. ¿Quieres generar ese PDF?',run,'Generar PDF con pendientes');else await run();}
  document.addEventListener('click',event=>{
    const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
    if(action==='stage')setStage(Number(el.dataset.stage));else if(action==='previous')setStage(state.stage-1);else if(action==='next')setStage(state.stage+1);
    else if(action==='save')saveFile();else if(action==='load')$('#load-file').click();else if(action==='close-modal')closeModal();else if(action==='help')help();else if(action==='reset')reset();else if(action==='reset-current')resetCurrent();
    else if(action==='work-area'){state.workArea=el.dataset.area;state.tool='disks';selected=firstSelection();persist();render();}
    else if(action==='tool'){state.tool=el.dataset.tool;persist();render();}
    else if(action==='select-part'){selected={diskId:el.dataset.disk,partId:el.dataset.part};render();}
    else if(action==='disk-operation')operationModal(el.dataset.operation);else if(action==='properties')properties();else if(action==='copy')copyModal(el.dataset.disk,el.dataset.part);
    else if(action==='test-format'){const id=el.dataset.id,t=state.formatTests[id]||{};if(!t.choice){toast('Elige primero un sistema de archivos.');return;}C.testFormat(state,id,t.choice);persist();render();}
    else if(action==='test-incident'){
      const id=el.dataset.id,t=state.incidentTests[id]||{};
      if(t.active)return;
      if(!t.selectedPlan){toast('Selecciona un plan antes de ejecutarlo.');return;}
      confirmModal('Ejecutar el plan elegido','Se aplicará el plan y se guardará tu decisión. Después observarás las consecuencias y podrás analizarlas, pero no elegir otro plan en esta incidencia.',()=>{C.testIncident(state,id,t.selectedPlan);persist();render();},'Ejecutar y observar');
    }
    else if(action==='pdf')pdf();
  });
  $('#load-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>8*1024*1024){toast('El archivo es demasiado grande para un progreso de DiscoLab.');return;}let loaded;try{loaded=C.validateSave(JSON.parse(await file.text()));}catch(error){toast('No se ha cargado el archivo: '+error.message);return;}confirmModal('Cargar progreso','Se recuperará el progreso de '+(loaded.names.trim()||'alumnado sin nombre')+'. La práctica actual será sustituida. Guarda antes si quieres conservarla.',()=>{state=loaded;selected={diskId:'data',partId:'original'};persist();render();toast('Progreso cargado. Puedes continuar la práctica.');},'Cargar este progreso');});
  document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveFile();}});
  window.addEventListener('pagehide',persist);
  render();persist();
})();
